import SheetMusicAudioCore
import SheetMusicFoundation
import Wirelet

/// Codec for a ``PreviewPlan`` — Swift → Kotlin direction. The Android engine asks the shared
/// ``NotePreviewPolicy`` what an audition should do and executes the answer, so only the encoder is here.
///
/// Wire layout (generated by `@WireFormat` on `PreviewPlanWire`):
/// ```
/// i64 generation
/// [PreviewVoiceWire] supersededVoices   ← empty = nothing to silence first
/// [PreviewVoiceWire] voices             ← never empty
/// i32 velocity
/// u8  isDrum                            ← 0 = false, 1 = true
/// i32 ringMilliseconds
/// i32 releaseTailMilliseconds
/// [PreviewPitchBendWire] pitchBends     ← empty = no wheel to move
/// ```
public enum PreviewPlanCodec {
    public static func encode(_ plan: PreviewPlan) -> Data {
        PreviewPlanWire(from: plan).encodeToData()
    }
}

/// One audition note on the wire: `i32 channel, i32 pitch`.
@WireFormat
package struct PreviewVoiceWire {
    var channel: Int32
    var pitch: Int32

    init(from voice: PreviewVoice) {
        channel = Int32(voice.channel)
        pitch = Int32(voice.pitch)
    }
}

/// One pitch-wheel move on the wire: `i32 channel, i32 value` (14-bit, 8192 the center).
@WireFormat
package struct PreviewPitchBendWire {
    var channel: Int32
    var value: Int32

    init(from bend: PreviewPitchBend) {
        channel = Int32(bend.channel)
        value = Int32(bend.value)
    }
}

@WireFormat
package struct PreviewPlanWire {
    var generation: Int64
    var supersededVoices: [PreviewVoiceWire]
    var voices: [PreviewVoiceWire]
    var velocity: Int32
    var isDrum: Bool
    var ringMilliseconds: Int32
    var releaseTailMilliseconds: Int32
    var pitchBends: [PreviewPitchBendWire]

    init(from plan: PreviewPlan) {
        generation = Int64(bitPattern: plan.generation)
        supersededVoices = plan.supersededVoices.map(PreviewVoiceWire.init(from:))
        voices = plan.voices.map(PreviewVoiceWire.init(from:))
        velocity = Int32(plan.velocity)
        isDrum = plan.isDrum
        ringMilliseconds = Int32(plan.ringMilliseconds)
        releaseTailMilliseconds = Int32(plan.releaseTailMilliseconds)
        pitchBends = plan.pitchBends.map(PreviewPitchBendWire.init(from:))
    }
}

/// Audition pitch wheels packed two bytes each, little-endian — each struck note's wheel, in the order of the
/// `PreviewVoicePairs` they go with. Empty for "all centered". 14 bits a note do not earn a wire type of their own.
public enum PreviewBendPairs {
    public static func encode(_ bends: [UInt16]) -> Data {
        var bytes = Data(capacity: bends.count * 2)
        for bend in bends {
            bytes.append(UInt8(bend & 0xFF))
            bytes.append(UInt8(bend >> 8))
        }
        return bytes
    }

    /// The wheels `bytes` packs; a trailing odd byte is ignored.
    public static func decode(_ bytes: Data) -> [UInt16] {
        let raw = [UInt8](bytes)
        return stride(from: 0, to: raw.count - 1, by: 2).map { UInt16(raw[$0]) | UInt16(raw[$0 + 1]) << 8 }
    }
}

/// Audition notes packed two bytes each, `channel` then `pitch` — how the JNI entry points take the notes to strike
/// and answer the notes to silence. Empty for none. Two bytes a note do not earn a wire type of their own.
public enum PreviewVoicePairs {
    public static func encode(_ voices: [PreviewVoice]) -> Data {
        var bytes = Data(capacity: voices.count * 2)
        for voice in voices {
            bytes.append(voice.channel)
            bytes.append(voice.pitch)
        }
        return bytes
    }

    /// The notes `bytes` packs; a trailing odd byte is ignored.
    public static func decode(_ bytes: Data) -> [PreviewVoice] {
        let raw = [UInt8](bytes)
        return stride(from: 0, to: raw.count - 1, by: 2).map { PreviewVoice(channel: raw[$0], pitch: raw[$0 + 1]) }
    }
}

/// A ``NotePreviewPolicy`` behind a lock, for the JNI entry points.
///
/// The policy is a value type on purpose — it stays testable on the host and portable to WebAssembly — and the
/// Apple engine, being main-actor isolated, needs nothing more. Android does: `playPreview` runs on whatever
/// thread sounded the note (an editing session has its own), while the end action runs on a coroutine
/// dispatcher, so the two reach the policy concurrently. This is the smallest thing that makes that safe, and it
/// lives on the bridge side so the shared type does not carry a lock nobody else needs.
public final class NotePreviewCoordinator: @unchecked Sendable {
    private let lock = SerialLock(label: "SheetMusicBridgeCore.NotePreviewCoordinator")
    private var policy = NotePreviewPolicy()

    public init() {}

    /// Plans one audition of `voices` struck together, each at its wheel in `bends` (empty: all centered); `nil` for
    /// none, leaving whatever is sounding alone.
    public func begin(
        voices: [PreviewVoice],
        bends: [UInt16] = [],
        velocity: UInt8,
        isDrum: Bool,
        ringMilliseconds: Int,
    ) -> PreviewPlan? {
        lock.withLock {
            policy.begin(
                voices: voices, bends: bends, velocity: velocity, isDrum: isDrum, ringMilliseconds: ringMilliseconds,
            )
        }
    }

    public func endVoices(generation: UInt64) -> [PreviewVoice] {
        lock.withLock { policy.endVoices(generation: generation) }
    }

    public func silenceVoices() -> [PreviewVoice] {
        lock.withLock { policy.silenceVoices() }
    }
}
